char read_repeating_text_input_key_code();

void cRBorder::InputText()
{
    char* insertion_end;
    char final_character;
    char key = read_repeating_text_input_key_code();

    if ((input_flags & 0x0c) != 0) {
        input_ok_state()->AI();
        if ((input_ok_state()->ok_widget->widget_flags
                & FRONTEND_WIDGET_FLAG_PRIMARY_ACTION_TRIGGERED)
            != 0)
            goto finish_input;
    }

    if (key == 5
        || (widget_flags & FRONTEND_WIDGET_FLAG_TEXT_INPUT_SUBMIT_REQUESTED) != 0)
        goto finish_input;

    if (key == 6 && (input_flags & 1) == 0) {
        if ((input_flags & 2) == 0) {
            text_buffer[input_cursor] = '>';
            ++input_cursor;

            char carry = ' ';
            char next = text_buffer[input_cursor];
            insertion_end = &text_buffer[input_cursor];
            final_character = carry;
            while (next != 0) {
                char displaced = next;
                *insertion_end++ = carry;
                next = *insertion_end;
                carry = displaced;
                final_character = displaced;
            }
            goto finish_insertion;
        }
    } else if (key == 3) {
        int cursor = input_cursor;
        if (cursor > 0) {
            char* current = &text_buffer[cursor];
            char old = *current;
            char previous = current[-1];
            *current = previous;
            current[-1] = old;
            int updated_cursor = input_cursor - 1;
            input_cursor = updated_cursor;
        }
    } else if (key == 4) {
        int cursor = input_cursor;
        if (cursor < input_length) {
            char* current = &text_buffer[cursor];
            char old = *current;
            char next = current[1];
            *current = next;
            current[1] = old;
            int updated_cursor = input_cursor + 1;
            input_cursor = updated_cursor;
        }
    } else if (key == 7) {
        int pos = input_cursor;
        int column = -1;
        while (pos > 0) {
            if (text_buffer[pos] == '>')
                break;
            ++column;
            --pos;
        }
        if (text_buffer[pos] == '>')
            --pos;

        if (pos != 0) {
            int next_column = 0;
            while (pos > 0) {
                if (text_buffer[pos] == '>')
                    break;
                ++next_column;
                --pos;
            }
            if (text_buffer[pos] == '>')
                ++pos;
            if (column > next_column)
                column = next_column;

            char* remove = &text_buffer[input_cursor];
            while (*remove != 0) {
                *remove = remove[1];
                ++remove;
            }

            input_cursor = pos + column;
            char* insert = &text_buffer[input_cursor];
            char carry = *insert;
            do {
                char next = insert[1];
                insert[1] = carry;
                ++insert;
                carry = next;
            } while (*insert != 0);
        }
    } else if (key == 8) {
