            *remove = remove[1];
            ++remove;
        }

        input_cursor = separator - 1;
        char* insert = &text_buffer[input_cursor];
        char carry = *insert;
        do {
            char next = insert[1];
            insert[1] = carry;
            ++insert;
            carry = next;
        } while (*insert != 0);
    } else if (key == 10) {
        int pos = input_cursor;
        while (pos > 0 && text_buffer[pos] != '>')
            --pos;
        if (text_buffer[pos] == '>')
            ++pos;

        char* remove = &text_buffer[input_cursor];
        while (*remove != 0) {
            *remove = remove[1];
            ++remove;
        }

        input_cursor = pos;
        char* insert = &text_buffer[input_cursor];
        char carry = *insert;
        do {
            char next = insert[1];
            insert[1] = carry;
            ++insert;
            carry = next;
        } while (*insert != 0);
    } else if (key == 1) {
        int cursor = input_cursor;
        if (cursor > 0) {
            --cursor;
            input_cursor = cursor;
            char* remove = &text_buffer[cursor];
            while (*remove != 0) {
                *remove = remove[1];
                ++remove;
            }
            --input_length;
        }
    } else if (key == 2) {
        int cursor = input_cursor;
        if (cursor < input_length) {
            char* remove = &text_buffer[cursor];
            while (*remove != 0) {
                *remove = remove[1];
                ++remove;
            }
            --input_length;
        }
    } else if (key != 0) {
        if (input_length < input_capacity
            && (key != ' ' || (input_flags & 1) == 0)
            && ((input_flags & 2) == 0 || (key != ',' && key != '.'))) {
            text_buffer[input_cursor] = key;
            ++input_cursor;

            char carry = ' ';
            char next = text_buffer[input_cursor];
            insertion_end = &text_buffer[input_cursor];
            final_character = carry;
            while (next != 0) {
                char displaced = next;
                *insertion_end++ = carry;
                next = *insertion_end;
                carry = displaced;
                final_character = displaced;
            }
            goto finish_insertion;
        }
    }

    goto input_postprocess;
finish_insertion:
    *insertion_end = final_character;
    insertion_end[1] = 0;
    ++input_length;
input_postprocess:
    if ((input_flags & 2) != 0) {
        int index = 0;
        char ch = text_buffer[0];
        while (ch != 0) {
            if (text_buffer[index] != ' ' && index != input_cursor)
                break;
            if (index != input_cursor) {
                char* remove = &text_buffer[index];
                while (*remove != 0) {
                    *remove = remove[1];
                    ++remove;
                }
                if (index <= input_cursor)
                    --input_cursor;
                --input_length;
            }
            ch = text_buffer[index++ + 1];
        }
    }

    input_cursor_blink_progress += input_cursor_blink_step;
    if (input_cursor_blink_progress > 1.0f) {
        input_cursor_blink_progress = 0.0f;
        input_cursor_visible = input_cursor_visible == 0;
    }

    if (input_cursor_visible == 1)
        text_buffer[input_cursor] = '|';
    else
        text_buffer[input_cursor] = ' ';
    RePosition();
    return;

finish_input:
    char* remove = &text_buffer[input_cursor];
    while (*remove != 0) {
        *remove = remove[1];
        ++remove;
    }
    unsigned int original_flags = widget_flags;
    unsigned int cleared_flags =
        original_flags & ~FRONTEND_WIDGET_FLAG_TEXT_INPUT_ACTIVE;
    int remaining_length = input_length - 1;
    unsigned int closing_flags =
        original_flags & ~FRONTEND_WIDGET_FLAG_TEXT_INPUT_ACTIVE;
    closing_flags |= FRONTEND_WIDGET_FLAG_TEXT_INPUT_COMPLETE;
    widget_flags = cleared_flags;
    input_length = remaining_length;
    widget_flags = closing_flags;
    RePosition();
    if ((input_flags & 0x0c) != 0)
        g_game->border_manager
            .kill_border(input_ok_state()->ok_widget);
}
